@sig trait ObstacleEvidenceAssessor_Api {
  def id: Art.BridgeId
  def obstacle_evidence_Id : Art.PortId
  def obstacle_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var obstacle_assessment: Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment = $

  def put_obstacle_assessment(value : Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment) : Unit = {
    Contract(
      Modifies(obstacle_assessment),
      Ensures(
        obstacle_assessment == value
      )
    )
    Spec {
      obstacle_assessment = value
    }

    Art.putValue(obstacle_assessment_Id, Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ObstacleEvidenceAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val obstacle_evidence_Id : Art.PortId,
  val obstacle_assessment_Id : Art.PortId) extends ObstacleEvidenceAssessor_Api

@datatype class ObstacleEvidenceAssessor_Operational_Api (
  val id: Art.BridgeId,
  val obstacle_evidence_Id : Art.PortId,
  val obstacle_assessment_Id : Art.PortId) extends ObstacleEvidenceAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var obstacle_evidence: Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence = $

  def get_obstacle_evidence() : Option[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence] = {
    Contract(
      Ensures(
        Res == Some(obstacle_evidence)
      )
    )
    val value : Option[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence] = Art.getValue(obstacle_evidence_Id) match {
      case Some(Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port obstacle_evidence.  Expecting 'Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence_Payload' but received ${v}")
        None[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence]()
      case _ => None[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence]()
    }
    return value
  }
}
